void FillRound(HDC dc,const RECT& r,COLORREF color,int radius=16){HBRUSH brush=CreateSolidBrush(color);HBRUSH old=static_cast<HBRUSH>(SelectObject(dc,brush));HPEN oldPen=static_cast<HPEN>(SelectObject(dc,GetStockObject(NULL_PEN)));RoundRect(dc,r.left,r.top,r.right,r.bottom,radius,radius);SelectObject(dc,oldPen);SelectObject(dc,old);DeleteObject(brush);}
